############################################################ # Body ############################################################
BEGIN_PGML Consider the set of 7-bit strings of weight 3. That is, strings of 0s and 1s that are seven characters long and have exactly three 1s. How many such strings are there?
END_PGML
############################################################ # Scaffold ############################################################ Scaffold::Begin(numbered => 1,is_open => "correct_or_first_incorrect",can_open => when_previous_correct,);
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML Give the answer as a single binomial coefficient.
[_]{$ans1}{5}
END_PGML
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML Now count just those 7-bit strings of weight 3 that start with a 1. How many are there?
[_]{$ans2}{5}
END_PGML
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML Now count just those 7-bit strings of weight 3 that start with 01. How many are there?
[_]{$ans3}{5}
END_PGML
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML Now count just those 7-bit strings of weight 3 that start with 001. How many are there?
[_]{$ans4}{5}
END_PGML
Section::End();
############################################################ # Section ############################################################ Section::Begin("");
BEGIN_PGML Continue this process until you have counted all 7-bit strings of weight 3, as a _sum_ of binomial coefficients. What is this sum?
[_]{$ans1}{20}
END_PGML
